describe('Invalid Card Number Error Handling', () => {
  beforeEach(() => {
    cy.visit('/payment');
  });

  it('should display error message when entering invalid card number', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment').as('processPayment');

    // Fill in valid form fields
    cy.get('[data-testid="card-holder-name"]').type('John Doe');
    cy.get('[data-testid="card-number"]').type('123456789012345');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="card-type"]').click();
    cy.get('[data-testid="card-type-visa"]').click();

    // Attempt to submit the form
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for the API call
    cy.wait('@processPayment');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid card number');

    // Verify form is not submitted
    cy.get('[data-testid="payment-success-message"]')
      .should('not.exist');

    // Verify card number field still has value
    cy.get('[data-testid="card-number"]').should('have.value', '123456789012345');
  });

  it('should not display error when entering valid card number', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment', {
      statusCode: 200,
      body: { success: true, transactionId: 'txn_12345' }
    }).as('processPayment');

    // Fill in valid form fields
    cy.get('[data-testid="card-holder-name"]').type('Jane Smith');
    cy.get('[data-testid="card-number"]').type('4928 1617 0000 1234');
    cy.get('[data-testid="expiry-date"]').type('12/26');
    cy.get('[data-testid="cvv"]').type('412');
    cy.get('[data-testid="card-type"]').click();
    cy.get('[data-testid="card-type-mastercard"]').click();

    // Submit the form
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for the API call
    cy.wait('@processPayment');

    // Verify success message is displayed
    cy.get('[data-testid="payment-success-message"]')
      .should('be.visible')
      .should('contain', 'Payment successful');

    // Verify error message does not exist
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify form is cleared or reset
    cy.get('[data-testid="card-number"]').should('have.value', '');
  });
});
